$want = @('context:pets','context:pets-horses-birds-and-other-companions','context:pets-life-together','context:pets-memorial-without-the-cliches','context:pets-more-than-one','context:pets-paws-noses-tags-and-real-marks','context:pets-portrait-ten-different-ways','context:pets-push-pets','context:pets-the-little-things-that-make-them-them','context:pets-this-is-my-pet','context:pets-turn-my-pet-into-art')
$tmp = Join-Path $env:TEMP "aura-ctx-pets.json"
